entries[438583] = { ["name"] = "Instabile Energie", ["text"] = "Sofort\nWenn Instabile Fragmente aufgehoben werden, werden Heilung und Schaden gegen ' Verstärkter Panzer ' 30 Sek. lang um 50% erhöht. Dieser Effekt ist stapelbar.\n\nZusätzlich fügt ' Instabile Energie ' allen betroffenen Spielercharakteren alle 2 Sek. 363667 Schattenschaden zu." }
entries[438586] = { ["name"] = "Säurehagel", ["text"] = "Unbegrenzte Reichweite\nWirken in 1 sek. 9 sek. Abklingzeit\nNezarox beschwört einen Gifthagel für 4 Sek., dessen Geschosse 575632 Naturschaden verursachen und Spielercharaktere innerhalb von 4 Metern um jeden Einschlag mit ' Haftendes Toxin ' belegen." }
entries[438587] = { ["name"] = "Masseneruption", ["text"] = "Ermächtigte Zauber lassen Eure nächste Eruption bis zu 3 Ziele treffen. Wenn weniger als 3 Ziele getroffen werden, wird der Schaden von 'Masseneruption' für jedes fehlende Ziel um 15% erhöht." }
