entries[438590] = { ["name"] = "Mit beiden Füßen auf dem Boden", ["text"] = "Verringert den erlittenen körperlicher Schaden um 2%.\n\n'Donnerexplosion' verringert Euren erlittenen Schaden 5 Sek. lang um 8%.\n(100ms Abklingzeit)" }
