entries[438592] = { ["name"] = "Serum der zügellosen Kampfeslust", ["text"] = "Sofort 1 min Abklingzeit\nKonsumiert methodisch eine kleine Dose des Serums, wenn Ihr Euch in den Kampf stürzt, um Eure Sinne bis an ihre Grenzen zu schärfen.\nIn diesem Zustand besteht beim Parieren und Ausweichen eine Chance, dem Angreifer mit 'Konter' zu begegnen und ihm Y körperlichen Schaden zufügen." }
entries[438593] = { ["name"] = "Lieblingsgericht", ["text"] = "100 Meter Reichweite\nSofort\nBenk Sumsebrumm beschwört Fässer mit köstlichem Honig. Ein Zusammenstoß fügt Spielercharakteren, die sich im Umkreis von 3 Metern um den Aufprall befinden, 12122247 körperlichen Schaden zu.\n\nDer Geruch des Honigs lockt alle 30 Sek. eine gefräßige Glutbiene an." }
entries[438595] = { ["name"] = "Feuerüberschuss", ["text"] = "Frost\nWenn Ihr 'Kometenhagel' einsetzt, explodiert Euer nächster Einsatz von 'Eislanze' in einem 'Frostfeuerausstoß', der Gegnern in der Nähe (265.6% der Zaubermacht) Frostfeuerschaden zufügt. Fügt Zielen über 8 Ziele hinaus verringerten Schaden zu.\n\n'Frostfeuerausstoß' hat eine Chance von 50%, 'Hirnfrost' zu gewähren.\n\nFeuer\nWenn Ihr 'Meteor' einsetzt, explodiert Euer nächster Einsatz von 'Feuerschlag' in einem 'Frostfeuerausstoß', der Gegnern in der Nähe (265.6% der Zaubermacht) Frostfeuerschaden zufügt. Fügt Zielen über 8 Ziele hinaus verringerten Schaden zu.\n\n'Frostfeuerausstoß' verringert die Abklingzeit von 'Phönixflammen' um 5 Sek." }
entries[438597] = { ["name"] = "Sturmschild", ["text"] = "Wenn Ihr 'Einschreiten' bei einem Ziel einsetzt, gewährt ihm das einen Schild, der 5 Sek. lang anhält und Magieschaden in Höhe des 3-Fachen Eurer Rüstung absorbiert." }
entries[438598] = { ["name"] = "Sturmschild", ["text"] = "Unbegrenzte Reichweite\nSofort\nWenn Ihr 'Einschreiten' bei einem Ziel einsetzt, gewährt ihm das einen Schild, der 5 Sek. lang anhält und Magieschaden in Höhe des 3-Fachen Eurer Rüstung absorbiert." }
entries[438599] = { ["name"] = "Bluthieb", ["text"] = "40 Meter Reichweite\nSofort\nSchlägt einen Spielercharakter und lässt ihn bluten, wodurch er 3 Sek. lang alle 0.5 Sek. 181834 körperlichen Schaden erleidet. Dieser Effekt ist stapelbar." }
entries[438600] = { ["name"] = "Frostüberschuss", ["text"] = "Frost\nWenn Ihr 'Feuerüberschuss' verbraucht, löst Euer nächster Einsatz von 'Hagel' zusätzlich 'Eisnova' mit 150% Effektivität aus.\n\nWenn Ihr 'Frostüberschuss' verbraucht, wird die Abklingzeit von 'Kometenhagel' um 3 Sek verringert.\n\nFeuer\nWenn Ihr 'Feuerüberschuss' verbraucht, löst Euer nächster Einsatz von 'Phönixflammen' zusätzlich 'Eisnova' mit 200% Effektivität aus.\n\nWenn Ihr 'Frostüberschuss' verbraucht, wird die Abklingzeit von 'Meteor' um 5 Sek verringert." }
entries[438601] = { ["name"] = "Schwarzblut", ["text"] = "Unbegrenzte Reichweite\nSofort\nVerursacht alle 1 Sek. 5 Schattenschaden.\n\nBewegungsgeschwindigkeit um 30 % verringert." }
