entries[438606] = { ["name"] = "Draenischer Holostein", ["text"] = "Wirken in 10 sek. 30 min Abklingzeit\n1 Aufladung\nBringt Euch zurück nach: Ruhestein-Ort. Sprecht mit einem Gastwirt an einem anderen Ort, um Euren Heimatort zu ändern.\n\nNur Draenei und Lichtgeschmiedete Draenei können den draenischen Holostein verwenden." }
entries[438607] = { ["name"] = "Meteor", ["text"] = "100 Meter Reichweite\nSofort\nRuft einen Meteor herab, der nach 3 Sek. am Zielort einschlägt. Fügt allen Gegnern (444% der Zaubermacht) Feuerschaden zu und verbrennt den Boden, um allen Gegnern im Gebiet im Verlauf von 8.5 Sek. [8 * (8.53875% der Zaubermacht)] Feuerschaden zuzufügen.\n\nDer Gegner, der am nächsten zum Zentrum des Einschlags ist, erleidet 40% mehr Schaden. Der Schaden ist nach dem 8. Ziel verringert." }
entries[438608] = { ["name"] = "Meteor", ["text"] = "100 Meter Reichweite\nSofort\nRuft einen Meteor herab, der nach 3 Sek. am Zielort einschlägt. Fügt allen Gegnern (444% der Zaubermacht) Feuerschaden zu und verbrennt den Boden, um allen Gegnern im Gebiet im Verlauf von 8.5 Sek. [8 * (8.53875% der Zaubermacht)] Feuerschaden zuzufügen.\n\nDer Gegner, der am nächsten zum Zentrum des Einschlags ist, erleidet 40% mehr Schaden. Der Schaden ist nach dem 8. Ziel verringert." }
entries[438609] = { ["name"] = "Kometenhagel", ["text"] = "100 Meter Reichweite\nSofort\nLässt eine Folge von 7 Eiskometen auf das Ziel und seine Umgebung herabfallen, die allen Gegnern innerhalb von 6 Metern um die Einschlagsorte bis zu [7 * (55% der Zaubermacht)] Frostschaden zufügt." }
entries[438611] = { ["name"] = "Frostüberschuss", ["text"] = "Sofort\nFrost\nWenn Ihr 'Feuerüberschuss' verbraucht, löst Euer nächster Einsatz von 'Hagel' zusätzlich 'Eisnova' mit 150% Effektivität aus.\n\nWenn Ihr 'Frostüberschuss' verbraucht, wird die Abklingzeit von 'Kometenhagel' um 3 Sek verringert.\n\nFeuer\nWenn Ihr 'Feuerüberschuss' verbraucht, löst Euer nächster Einsatz von 'Phönixflammen' zusätzlich 'Eisnova' mit 150% Effektivität aus.\n\nWenn Ihr 'Frostüberschuss' verbraucht, wird die Abklingzeit von 'Meteor' um 3 Sek verringert.\n(750ms Abklingzeit)" }
