entries[438947] = { ["name"] = "Toxinnova", ["text"] = "Sofort\nAnsurek entfesselt einen Ring aus Gift, der Spielercharakteren innerhalb von 8 Metern 28781576 Naturschaden zufügt.\n\nDer Ring breitet sich aus, fügt Spielercharakteren, die ihn berühren, 15 Sek. lang alle 0.5 Sek. 2014710 Naturschaden zu und verlangsamt sie um 60%.\n\n' Reaktionsdampf ' bildet sich, wenn der Ring in Kontakt mit ' Reaktiver Schaum ' kommt." }
entries[438949] = { ["name"] = "Gieriger Biss", ["text"] = "200 Meter Reichweite\nSofort\nAvanoxx springt zu ihrem Primärziel und beißt es 3-mal schnell hintereinander. Jeder Biss verursacht 6061123 körperlichen Schaden und der letzte Biss erhöht den erlittenen Schaden 10 Sek. lang um 50%." }
