entries[438960] = { ["name"] = "Gespinstschleuder", ["text"] = "200 Meter Reichweite\nSofort\nAvanoxx schleudert toxische Spinnweben in alle Richtungen, die allen Spielercharakteren 5 Sek. lang alle 1 Sek. 909169 Naturschaden zufügen.\n\nAußerdem hinterlässt dies an den Positionen von Zielen ' Widerliche Spinnweben ', wodurch Spielercharaktere innerhalb von 2.5 Metern um jeden Einschlagsort 4848899 Naturschaden erleiden." }
entries[438961] = { ["name"] = "Sporenverschmolzene Kräuter überladen", ["text"] = "5 Meter Reichweite\nWirken in 5.3 sek.\nDie Überladung von sporenverschmolzenen Kräutern löst eine Reaktion mit den magischen Sporen aus, wodurch ein seltsames Phänomen hervorgerufen wird.\n\nIn der Nähe erscheinen zahlreiche Kräuter. Wenn Kräuterkundige die richtigen Kräuter sammeln, bekommen sie echte Reagenzien und Materialien. Sammeln sie jedoch die falschen Kräuter, werden sie desorientiert und erleiden Schaden.\nEntdeckung:\nIrgendwo in Khaz Algar gefunden" }
