entries[439528] = { ["name"] = "Gedeihendes Wachstum", ["text"] = "Wildheit\nWenn 'Zerfetzen' oder 'Krallenhieb' Schaden verursacht, besteht eine Chance, das Opfer mit 'Blutsucherranken' zu belegen, was ihm im Verlauf von 6 Sek. (127.5% der Angriffskraft) Blutungsschaden zufügt.\n\n'Wildwuchs' und 'Nachwachsen' haben eine Chance, das Ziel mit 'Symbiotische Blüte' zu belegen und es im Verlauf von 6 Sek. um (180% der Zaubermacht) Gesundheit zu heilen.\n\nMehrere Instanzen können einander überlagern.\n\nWiederherstellung\nWenn 'Zerfetzen' oder 'Krallenhieb' Schaden verursacht, besteht eine Chance, das Opfer mit 'Blutsucherranken' zu belegen, was ihm im Verlauf von 6 Sek. (127.5% der Angriffskraft) Blutungsschaden zufügt.\n\n'Wildwuchs', 'Nachwachsen', und 'Erblühen' haben eine Chance, das Ziel mit 'Symbiotische Blüte' zu belegen und es im Verlauf von 6 Sek. um (180% der Zaubermacht) Gesundheit zu heilen.\n\nMehrere Instanzen können einander überlagern." }
entries[439530] = { ["name"] = "Symbiotische Blüte", ["text"] = "100 Meter Reichweite\nSofort\nWenn 'Zerfetzen' oder 'Krallenhieb' Schaden verursacht, besteht eine Chance, das Opfer mit 'Blutsucherranken' zu belegen, was ihm im Verlauf von 6 Sek. (127.5% der Angriffskraft) Blutungsschaden zufügt.\n\n[ Wildheit : 'Wildwuchs' und 'Nachwachsen' /\n\nWiederherstellung\n'Wildwuchs', 'Nachwachsen', und 'Erblühen' ] haben eine Chance, das Ziel mit 'Symbiotische Blüte' zu belegen und es im Verlauf von 6 Sek. um (180% der Zaubermacht) Gesundheit zu heilen.\n\nMehrere Instanzen können einander überlagern." }
