entries[439690] = { ["name"] = "Relikt der Sucher aus alten Zeiten", ["text"] = "Wenn Brann ' Sammelwerkzeuge ' einsetzt, besteht eine Chance von 20%, ein mächtiges Artefakt freizulegen, das Eurer Gruppe einen mächtigen Segen gewährt.\n\nSammelwerkzeuge\nBrann setzt seine Sammelwerkzeuge ein, um Spielercharakteren zu helfen, zusätzliches Gold, Erz, Leder, zusätzliche Kräuter, Fische und Schätze zu finden." }
