entries[439707] = { ["name"] = "Aqirit", ["text"] = "5 Meter Reichweite\nWirken in 2.5 sek.\nEin seltenes Metall, das überall auf Khaz Algar gefunden werden kann. Manchmal lässt es sich zwar an der Oberfläche finden, aber nahe Azj-Kahet nehmen seine Vorkommen zu. Auch wenn es viele Einsatzmöglichkeiten dafür gibt, sind vor allem Ingenieure daran interessiert, große Mengen davon zu kaufen." }
entries[439708] = { ["name"] = "Eisenklaue", ["text"] = "5 Meter Reichweite\nWirken in 2.5 sek.\nEin seltenes Metall, das überall auf Khaz Algar gefunden werden kann, vor allem nahe oder an der Oberfläche. Es ist berüchtigt für seine Widerstandsfähigkeit und deshalb äußerst beliebt bei Schmieden, die es am liebsten in großen Mengen kaufen wollen." }
entries[439709] = { ["name"] = "Reichhaltiges Bismut", ["text"] = "5 Meter Reichweite\nWirken in 2.5 sek.\nEin sehr seltenes Metall, das überall auf Khaz Algar gefunden werden kann. Obwohl es recht langweilig wirkt, wird es aufgrund seiner vielseitigen Eigenschaften besonders von begabten Handwerkern gerne in großen Mengen gekauft.\n\nGelegentlich finden sich unter der Oberfläche ungewöhnlich große Vorkommen, sehr zur Freude von Minenarbeitern, die damit ihr tägliches Brot verdienen." }
entries[439710] = { ["name"] = "Reichhaltiges Aqirit", ["text"] = "5 Meter Reichweite\nWirken in 2.5 sek.\nEin seltenes Metall, das überall auf Khaz Algar gefunden werden kann. Manchmal lässt es sich zwar an der Oberfläche finden, aber nahe Azj-Kahet nehmen seine Vorkommen zu. Auch wenn es viele Einsatzmöglichkeiten dafür gibt, sind vor allem Ingenieure daran interessiert, große Mengen davon zu kaufen.\n\nGelegentlich finden sich unter der Oberfläche ungewöhnlich große Vorkommen, sehr zur Freude von Minenarbeitern, die damit ihr tägliches Brot verdienen." }
entries[439711] = { ["name"] = "Reichhaltige Eisenklaue", ["text"] = "5 Meter Reichweite\nWirken in 2.5 sek.\nEin seltenes Metall, das überall auf Khaz Algar gefunden werden kann, vor allem nahe oder an der Oberfläche. Es ist berüchtigt für seine Widerstandsfähigkeit und deshalb äußerst beliebt bei Schmieden, die es am liebsten in großen Mengen kaufen wollen.\n\nGelegentlich finden sich unter der Oberfläche ungewöhnlich große Vorkommen, sehr zur Freude von Minenarbeitern, die damit ihr tägliches Brot verdienen." }
entries[439712] = { ["name"] = "Bismutflöz", ["text"] = "5 Meter Reichweite\nWirken in 2.5 sek.\nEin sehr seltenes Metall, das überall auf Khaz Algar gefunden werden kann. Obwohl es recht langweilig wirkt, wird es aufgrund seiner vielseitigen Eigenschaften besonders von begabten Handwerkern gerne in großen Mengen gekauft.\n\nSelbst unter der Oberfläche sind metallreiche Flöze ein eher seltener und aufregender Anblick. Man findet sie gewöhnlicherweise an Wänden oder Decken in besonders engen Räumen." }
entries[439713] = { ["name"] = "Aqiritflöz", ["text"] = "5 Meter Reichweite\nWirken in 2.5 sek.\nEin seltenes Metall, das überall auf Khaz Algar gefunden werden kann. Manchmal lässt es sich zwar an der Oberfläche finden, aber nahe Azj-Kahet nehmen seine Vorkommen zu. Auch wenn es viele Einsatzmöglichkeiten dafür gibt, sind vor allem Ingenieure daran interessiert, große Mengen davon zu kaufen.\n\nSelbst unter der Oberfläche sind metallreiche Flöze ein eher seltener und aufregender Anblick. Man findet sie gewöhnlicherweise an Wänden oder Decken in besonders engen Räumen." }
entries[439714] = { ["name"] = "Eisenklauenflöz", ["text"] = "5 Meter Reichweite\nWirken in 2.5 sek.\nEin seltenes Metall, das überall auf Khaz Algar gefunden werden kann, vor allem nahe oder an der Oberfläche. Es ist berüchtigt für seine Widerstandsfähigkeit und deshalb äußerst beliebt bei Schmieden, die es am liebsten in großen Mengen kaufen wollen.\n\nSelbst unter der Oberfläche sind metallreiche Flöze ein eher seltener und aufregender Anblick. Man findet sie gewöhnlicherweise an Wänden oder Decken in besonders engen Räumen." }
entries[439715] = { ["name"] = "Kristallisiertes Bismut", ["text"] = "5 Meter Reichweite\nWirken in 2.5 sek.\nEin sehr seltenes Metall, das überall auf Khaz Algar gefunden werden kann. Obwohl es recht langweilig wirkt, wird es aufgrund seiner vielseitigen Eigenschaften besonders von begabten Handwerkern gerne in großen Mengen gekauft.\n\nAufgrund ihrer Nähe zum Kernweg haben einige Vorkommen eine direkte Verbindung zur Weltenseele. Jeder Minenarbeiter erhält beim Abbau einen kleinen Segen sowie etwas kristallines Pulver, eine nützliche Reagenz für viele Herstellungsverfahren." }
entries[439716] = { ["name"] = "Kristallisiertes Aqirit", ["text"] = "5 Meter Reichweite\nWirken in 2.5 sek.\nEin seltenes Metall, das überall auf Khaz Algar gefunden werden kann. Manchmal lässt es sich zwar an der Oberfläche finden, aber nahe Azj-Kahet nehmen seine Vorkommen zu. Auch wenn es viele Einsatzmöglichkeiten dafür gibt, sind vor allem Ingenieure daran interessiert, große Mengen davon zu kaufen.\n\nAufgrund ihrer Nähe zum Kernweg haben einige Vorkommen eine direkte Verbindung zur Weltenseele. Jeder Minenarbeiter erhält beim Abbau einen kleinen Segen sowie etwas kristallines Pulver, eine nützliche Reagenz für viele Herstellungsverfahren." }
entries[439717] = { ["name"] = "Kristallisierte Eisenklaue", ["text"] = "5 Meter Reichweite\nWirken in 2.5 sek.\nEin seltenes Metall, das überall auf Khaz Algar gefunden werden kann, vor allem nahe oder an der Oberfläche. Es ist berüchtigt für seine Widerstandsfähigkeit und deshalb äußerst beliebt bei Schmieden, die es am liebsten in großen Mengen kaufen wollen.\n\nAufgrund ihrer Nähe zum Kernweg haben einige Vorkommen eine direkte Verbindung zur Weltenseele. Jeder Minenarbeiter erhält beim Abbau einen kleinen Segen sowie etwas kristallines Pulver, eine nützliche Reagenz für viele Herstellungsverfahren." }
entries[439718] = { ["name"] = "Heulendes Bismut", ["text"] = "5 Meter Reichweite\nWirken in 2.5 sek.\nEin sehr seltenes Metall, das überall auf Khaz Algar gefunden werden kann. Obwohl es recht langweilig wirkt, wird es aufgrund seiner vielseitigen Eigenschaften besonders von begabten Handwerkern gerne in großen Mengen gekauft.\n\nDas schwarze Blut der Alten Götter hat begonnen, sich unter Khaz Algar anzusammeln. Sein Schwären wirkt sich sogar auf die wertvollen Metalle aus, mit denen es in Berührung kommt. Jeder Minenarbeiter, der sich den tiefsten Tiefen stellt und derartige Vorkommen abbaut, wird Qualen erleiden, wie sie Sterbliche eigentlich nicht ertragen können. Glücklicherweise erhalten Überlebende dafür aber auch zappelnde Proben." }
