entries[439732] = { ["name"] = "Optimiertes Relikt", ["text"] = "Sofort\nAußerhalb eines Kampfes steigt die Bewegungsgeschwindigkeit der Gruppenmitglieder um 10%. Bei Kampfeintritt steigt das Tempo der Gruppenmitglieder 8 Sek. lang um 5%." }
