entries[439771] = { ["name"] = "Gezielter Schuss", ["text"] = "25 Energie 40 Meter Reichweite\nWirken in 2.5 sek. 12 sek. Abklingzeit\nBenötigt Einhändig\nEin machtvoller gezielter Schuss, der 0 körperlichen Schaden verursacht." }
