entries[439776] = { ["name"] = "Säurepfützen", ["text"] = "Unbegrenzte Reichweite\nSofort\n'Ätzspucke', 'Ätzender Hagel' und 'Walzende Säure' können 1.5 Min. lang ätzende Zonen bilden. Der Kontakt mit einer solchen Zone verursacht alle 0.5 Sek. 1582987 Naturschaden." }
entries[439777] = { ["name"] = "Säurepfützen", ["text"] = "Unbegrenzte Reichweite\nSofort\n'Ätzspucke', 'Ätzender Hagel' und 'Walzende Säure' können 1.5 Min. lang ätzende Zonen bilden. Der Kontakt mit einer solchen Zone verursacht alle 0.5 Sek. 1582987 Naturschaden." }
entries[439778] = { ["name"] = "Spinndrüsengespinstriss", ["text"] = "Unbegrenzte Reichweite\nSofort\nWenn ' Spinndrüsenstränge ' reißen, erleiden alle Spielercharaktere 690758 Naturschaden." }
entries[439779] = { ["name"] = "Spinndrüsenstränge", ["text"] = "Unbegrenzte Reichweite\nSofort\nRasha'nan beschießt markierte Ziele mit Netzen, die Spielercharakteren innerhalb von 0 Metern 2014711 Naturschaden zufügen, alle getroffenen Spielercharaktere fesseln und ' Klebrige Netze ' erschaffen. Die Fessel verursacht alle 1 Sek. 575632 Naturschaden und zieht Opfer nach innen.\n\nWenn die Fessel 0 Meter gedehnt wird, reißt sie und löst einen ' Spinndrüsengespinstriss ' aus." }
entries[439780] = { ["name"] = "Klebrige Netze", ["text"] = "Unbegrenzte Reichweite\nSofort\nDie ' Spinndrüsenstränge ' überziehen die Arena mit Seidenkleber, der alle 0.5 Sek. 115126 Naturschaden verursacht und die Bewegungsgeschwindigkeit um 20% verringert." }
