entries[439785] = { ["name"] = "Korrosion", ["text"] = "Unbegrenzte Reichweite\nSofort\nAbscheuliche Säure korrodiert das Ziel für 15 Sek., wodurch es alle 863447 Sek. 1.5 Naturschaden erleidet. Dieser Effekt ist stapelbar." }
entries[439786] = { ["name"] = "Walzende Säure", ["text"] = "Unbegrenzte Reichweite\nSofort\nRasha'nan stößt ein giftiges Gebräu auf markierte Ziele aus, das in Wellen vom Ziel aus in die angegebene Richtung schwappt.\n\nSpielercharaktere, die von der anfänglichen ätzenden Eruption bespritzt werden, erleiden ' Ätzende Benommenheit '.\n\nJeder Spielercharakter, der eine Welle berührt, wird um 50% verlangsamt und wird alle 1 Sek. mit ' Korrosion ' belegt.\n\nDie Wellen verbrennen ' Klebrige Netze ', fügen Spielcharakteren im Umkreis von 5 Metern 1726895 Naturschaden zu und erzeugen ' Säurepfützen '." }
entries[439787] = { ["name"] = "Ätzende Benommenheit", ["text"] = "Unbegrenzte Reichweite\nSofort\nDie ' Walzende Säure ' wird katapultartig ausgestoßen, verursacht 4029421 Naturschaden und betäubt Opfer für 1.5 Sek." }
entries[439789] = { ["name"] = "Walzende Säure", ["text"] = "Unbegrenzte Reichweite\nWirken in 2 sek.\nRasha'nan stößt ein giftiges Gebräu auf markierte Ziele aus, das in Wellen vom Ziel aus in die angegebene Richtung schwappt.\n\nSpielercharaktere, die von der anfänglichen ätzenden Eruption bespritzt werden, erleiden ' Ätzende Benommenheit '.\n\nJeder Spielercharakter, der eine Welle berührt, wird um 50% verlangsamt und wird alle 1 Sek. mit ' Korrosion ' belegt.\n\nDie Wellen verbrennen ' Klebrige Netze ', fügen Spielcharakteren im Umkreis von 5 Metern 1726895 Naturschaden zu und erzeugen ' Säurepfützen '." }
