entries[439792] = { ["name"] = "Klebrige Eruption", ["text"] = "100 Meter Reichweite\nSofort\nRasha'nan stößt wild Spinnweben aus, während sich keine Spielercharaktere in Nahkampfreichweite befinden, und verursacht 1439079 Naturschaden sowie zusätzlich 9 Sek. lang alle 3 Sek. 575632 Naturschaden. Dieser Effekt ist stapelbar." }
