entries[439794] = { ["name"] = "Netzbrecher", ["text"] = "Unbegrenzte Reichweite\nSofort\nRasha'nan hackt auf das Zielgebiet ein, verursacht 56987520 Naturschaden und zieht die Spielercharaktere zu sich. Diese Effekte verteilen sich gleichmäßig auf die Spielercharaktere im Umkreis von 8 Metern um den Einschlagsort.\n\nWenn 'Netzbrecher' nicht mindestens 4 Ziele trifft, erleiden alle Spielercharaktere den vollen Effekt." }
entries[439795] = { ["name"] = "Netzbrecher", ["text"] = "Unbegrenzte Reichweite\nWirken in 4 sek.\nRasha'nan hackt auf das Zielgebiet ein, verursacht 56987520 Naturschaden und zieht die Spielercharaktere zu sich. Diese Effekte verteilen sich gleichmäßig auf die Spielercharaktere im Umkreis von 8 Metern um den Einschlagsort.\n\nWenn 'Netzbrecher' nicht mindestens 4 Ziele trifft, erleiden alle Spielercharaktere den vollen Effekt." }
