entries[439814] = { ["name"] = "Seidengrab", ["text"] = "Wirken in 4 sek.\nAnsurek setzt alle Spielercharaktere in Spinnweben fest und fügt Spielercharakteren innerhalb von 2 Metern um den Einschlagsort der Spinnweben 3453789 Naturschaden zu. Diese Spinnweben fügen ihren Opfern alle 1 Sek. 575632 Naturschaden zu, bis sie zerstört werden.\n\nWenn Spinnweben zerstört werden, hinterlassen sie ' Packende Seide '." }
