entries[439818] = { ["name"] = "Götze der Erdenmutter", ["text"] = "Unbegrenzte Reichweite\nSofort\nBranns Zauber und Fähigkeiten haben eine Chance, den Götzen zu erwecken, was einem verletzten Spielercharakter einen Schild in Höhe von 15% seiner fehlenden Gesundheit gewährt." }
