entries[439837] = { ["name"] = "Unverwüstlicher Eisengötze", ["text"] = "Unbegrenzte Reichweite\nSofort\nWenn die Gesundheit eines Spielercharakters im Kampf unter 40% fällt, erwacht der Götze, fügt Gegnern in der Nähe moderaten körperlichen Schaden zu und verspottet sie für 4 Sek. Kann nur alle 2 Min. auftreten." }
entries[439838] = { ["name"] = "Netzbombe", ["text"] = "Wirken in 1.5 sek.\nTakazj verschießt klebrige Gespinstknoten in der Kammer, die die Bewegungsgeschwindigkeit von Spielercharakteren um 20% verringern und ihnen alle 1 Sek. 345379 körperlichen Schaden zufügen, während diese sich im Effektbereich befinden.\n\nDer Knoten in der Mitte bricht bei Berührung aus, was Spielercharakteren innerhalb von 10 Metern 1732248 Naturschaden zufügt und ' Bindende Netze ' einsetzt, um zwei Spielercharaktere mit aneinanderzubinden.\n\nWenn Anub'arash durch Stränge von 'Bindende Netze' stürmt, wird er 'Umschlungen'." }
