entries[439851] = { ["name"] = "Welle der Seelen", ["text"] = "Blut\n'Mal des Schnitters' sendet Ausbrüche von Schattenfrostenergie aus und holt sie zurück, die allen Gegnern, die sich im Weg befinden, auf beiden Strecken (84.0937% der Angriffskraft) Schattenfrostschaden zufügen.\n\nKritische Treffer mit 'Welle der Seelen' lassen Gegner 15 Sek. lang 5% mehr Schattenfrostschaden erleiden. Bis zu 2-mal stapelbar und trifft auf dem Rückweg immer kritisch.\n\nFrost\n'Mal des Schnitters' sendet Ausbrüche von Schattenfrostenergie aus und holt sie zurück, die allen Gegnern, die sich im Weg befinden, auf beiden Strecken (96.7079% der Angriffskraft) Schattenfrostschaden zufügen.\n\nKritische Treffer mit 'Welle der Seelen' lassen Gegner 15 Sek. lang 5% mehr Schattenfrostschaden erleiden. Bis zu 2-mal stapelbar und trifft auf dem Rückweg immer kritisch." }
